-- UK school media (logo, banner photo, description) from Wikipedia and Wikimedia Commons, free licences only.
-- Only fills empty fields; never overwrites. Six schools left out because the search matched the wrong page
-- (Warwick, Hartpury, Leeds College of Music, Edinburgh, Highlands and Islands, Robert Gordon University).
update schools s set
  logo_url = coalesce(nullif(s.logo_url,''), v.logo_url),
  logo_credit = case when coalesce(s.logo_url,'')='' then v.logo_credit else s.logo_credit end,
  image_url = coalesce(nullif(s.image_url,''), v.image_url),
  image_credit = case when coalesce(s.image_url,'')='' then v.image_credit else s.image_credit end,
  description = coalesce(nullif(s.description,''), v.description),
  description_credit = case when coalesce(s.description,'')='' then v.description_credit else s.description_credit end
from (values
('b9027acc-56c3-47da-9320-2b2a37a60169'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Manchester_University_Logo_%282%29.png/500px-Manchester_University_Logo_%282%29.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Whitworth_Hall.jpg/1280px-Whitworth_Hall.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: DrPhoenix, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Manchester is a public research university in Manchester, England, with its main campus south of the city centre on Oxford Road. It is  a red brick university, a product of the civic university movement of the late 19th century. The current institution was formed in 2004 through the merger of the University of Manchester Institute of Science and Technology and the Victoria University of Manchester.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('019e9a45-1c64-47f3-b9cb-3ecd680c0b6e'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Bar_42_UCE_Birmingham.JPG/1280px-Bar_42_UCE_Birmingham.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: David Waterson (DWaterson), CC BY-SA 3.0, Wikimedia Commons$q$,$q$Birmingham City University is a public university in Birmingham, England. Initially established as the Birmingham College of Art with roots dating back to 1843, it was designated as a polytechnic in 1971 and gained university status in 1992.
The university has two main campuses serving four faculties, and offers courses in art and design, business, the built environment, computing, education, engineering, English, healthcare, law, the performing arts, social sciences, and technology.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('9b3f2d36-2f11-45cc-bc7f-4a91495200ef'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Birkbeck%2C_University_of_London.png/500px-Birkbeck%2C_University_of_London.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Aduclehomo, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/6/67/Birkbeck_College%2C_University_of_London.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Matt From London, CC BY 2.0, Wikimedia Commons$q$,$q$Birkbeck College, University of London is a public research university located in the Bloomsbury district of London, England. It a member institution of the University of London. Established in 1823 as the London Mechanics' Institute by its founder Joseph Clinton Robertson and its supporters George Birkbeck, Jeremy Bentham, J. C. Hobhouse and Henry Brougham, Birkbeck is one of the few universities to specialise in evening higher education in the United Kingdom.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c7e5b00b-3c98-4941-9ebb-6c765089c0d5'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/London_Metropolitan_University_Logo.jpg/500px-London_Metropolitan_University_Logo.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: London Metropolitan University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Orion_Building_-Post_Graduate_Centre_of_London_Metropolitan_University-9June2009.jpg/1280px-Orion_Building_-Post_Graduate_Centre_of_London_Metropolitan_University-9June2009.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Alan Stanton, CC BY-SA 2.0, Wikimedia Commons$q$,$q$London Metropolitan University is a public research university in London, England. The University of North London and London Guildhall University merged in 2002 to create the university. The University's roots can be traced back to 1848.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f99739d9-e73d-4eba-8466-e197efb2b416'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/3/35/Abertaylib.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Tam155 at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$Abertay University is a public university in the city of Dundee, Scotland. In 1872, Sir David Baxter, 1st Baronet of Kilmaron, left a bequest for the establishment of a mechanics' institute in Dundee and the Dundee Institute of Technology was formed in 1888. As early as 1902 it was recognised by the Scottish Education Department as an educational hub, and was one of the first to be designated a central institution, akin to an "industrial university".$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ebb63931-52cf-4694-835c-381d2e1daa07'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/1/1a/School_of_World_Art_Studies.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: IWAM2009, CC0, Wikimedia Commons$q$,$q$The University of East Anglia is a public research university in Norwich, England. Established in 1963 on a 360-acre campus west of the city centre, the university has four faculties and twenty-six schools of study. It is one of five BBSRC funded research campuses, with forty businesses, four independent research institutes and a teaching hospital on site.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('794586fb-1f9e-4bb4-893b-2d037a30aff6'::uuid,NULL,NULL,NULL,NULL,$q$Harper Adams University is a land-based public university in Edgmond, Shropshire, United Kingdom. Established in 1901 as Harper Adams College, Harper Adams University gained university status in 2012 and is a member of the Land Based Colleges Aspiring to Excellence.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e1ad4597-7939-492b-aed9-2bd9d11f4cdb'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/The_Hive_-_Worcester_%2827415265175%29.jpg/1280px-The_Hive_-_Worcester_%2827415265175%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Esther Westerveld from Haarlemmermeer, Nederland, CC BY 2.0, Wikimedia Commons$q$,$q$The University of Worcester is a public research university, based in Worcester, England. With a history dating back to 1946, the university began awarding degrees in 1997 and was granted full university status in 2005.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('73a2eece-af4a-4b2b-bd36-b6cc4bb7388c'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/UWE_Bristol_logo.svg/500px-UWE_Bristol_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of the West of England, Bristol, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/a/a8/Uwe.bristol.750pix.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: The original uploader was Arpingstone at English Wikipedia., Public domain, Wikimedia Commons$q$,$q$The University of the West of England, also known as UWE Bristol, is a public research university, located in and around Bristol, England. With over 37,000 students and 4,200 staff, it is the largest provider of higher education in the South West of England.
The institution was formed as Bristol Polytechnic in 1970 and received university status in 1992, becaming the University of the West of England, Bristol.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('7dc2f30c-b488-4bd0-a09a-73febcb0b6b1'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Dundee_University_Scrymgeour.jpg/1280px-Dundee_University_Scrymgeour.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ydam, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Dundee is a public research university located in the city of Dundee, Scotland. It was founded as a university college in 1881 with a donation from the prominent Baxter family of textile manufacturers. The institution was, for most of its early existence, a constituent college of the University of St Andrews alongside United College and St Mary's College located in the town of St Andrews itself.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('30a59794-2f18-42d6-a864-1fc218fc68ec'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/University_of_Bristol.jpg/1280px-University_of_Bristol.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Simon Cobb, CC0, Wikimedia Commons$q$,$q$The University of Bristol is a public research university in Bristol, England. It received its royal charter in 1909, although it can trace its roots to University College, Bristol, established in 1876. Bristol Medical School, founded in 1833, was merged with the university college in 1893, and later became the university's school of medicine.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('1f4b219b-d8da-4f54-94b2-e972ad9d9d41'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/2/2e/GCUlogo_251px.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Glasgow Caledonian University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/1/13/GCU_Campus_View.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Knwwsss, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Glasgow Caledonian University, is a public university in Glasgow, Scotland. It was formed in 1993 by the merger of The Queen's College, Glasgow and Glasgow Polytechnic, founded in 1971).
It is located in the Cowcaddens district, just to the immediate north of the city centre, and is one of three universities in Glasgow alongside the University of Glasgow and the University of Strathclyde.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('83cb8ef5-8dcd-4dc1-932a-abfa36aaf51e'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Durham_-_Castle_-_02.jpg/1280px-Durham_-_Castle_-_02.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Benjamin Smith, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Durham, which operates under the trading name of Durham University, is a collegiate public research university in Durham, England, founded by an Act of Parliament in 1832 and incorporated by royal charter in 1837. It was the first recognised university to open in England for more than 600 years, after Oxford and Cambridge, and is thus identified by historians as the third-oldest university in England. As a collegiate university, its main functions are divided between the academic departments of the university and its 17 colleges.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('320c02e9-ef52-430e-885f-d1d10c6214d8'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/University_of_Derby_Library.jpg/1280px-University_of_Derby_Library.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Lianne99, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Derby, formerly known as Derby College, is a public university in the city of Derby, England. It traces its history back to the establishment of the Derby Diocesan Institution for the training of schoolmistresses in 1851. It gained university status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('cdbae795-0b76-4732-94a2-8a39b4700cf6'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/Marjon_campus_main_entrance.jpg/1280px-Marjon_campus_main_entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chris McKenna, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Plymouth Marjon University, commonly referred to as Marjon, is the trading name of the University of St Mark and St John, a university based primarily on a single campus on the northern edge of Plymouth, Devon, United Kingdom. Formerly named University College Plymouth St Mark & St John, the institution was awarded full university status in 2013.
The Vice-Chancellor of the university since 2023 is Professor Claire Taylor.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('909aeeb6-711a-4126-9a2d-16b9d55fd559'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Ncle_Union_2012.jpg/1280px-Ncle_Union_2012.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chemical Engineer, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Newcastle upon Tyne, which trades as Newcastle University, is a public research university based in Newcastle upon Tyne, England. It has overseas campuses in Singapore and Malaysia. The university is a red brick university and a founding member of the Russell Group, an association of research-intensive UK universities.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('dedea4a1-14e5-4b64-92e2-d0a5ecf73dcf'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/f/f5/University_Campus_Suffolk_-_geograph.org.uk_-_2839736.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: N Chadwick, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Suffolk is a public university situated in Suffolk and Norfolk, England. The university was established in 2007 as University Campus Suffolk, founded as a collaboration between the University of East Anglia and the University of Essex. The university's current name was adopted after it was granted independence in 2016 by the Privy Council and was awarded university status.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('b8398d6d-a234-46e9-b275-1d447d3a7d8f'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/TVU_Paragon_Campus_Brentford.jpg/1280px-TVU_Paragon_Campus_Brentford.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Sansmalrst, Public domain, Wikimedia Commons$q$,$q$The University of West London is a public research university in the England with campuses in Ealing, Brentford and Reading, Berkshire.
The university has roots in 1860 when the Lady Byron School was founded, later Ealing College of Higher Education. In 1992, the then-named Polytechnic of West London became a university as Thames Valley University.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('7378d03b-2904-41f3-ac6d-d52c5be57021'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/University_of_Sussex_Logo.svg/500px-University_of_Sussex_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Sussex, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Universit%C3%A4t_Sussex.jpg/1280px-Universit%C3%A4t_Sussex.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Uploaded on November 13, 2005; by TimBrighton, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Sussex is a public research university located in Falmer, East Sussex, England. It lies mostly within the city boundaries of Brighton and Hove. Its large campus site is surrounded by the South Downs National Park, and provides convenient access to central Brighton 5.5 kilometres away.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('309bee15-3f31-471a-a41b-6e51c252a7d5'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/6/67/University_of_Lincoln.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: H2d92, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Lincoln is a public research university in Lincoln, England, with origins dating back to 1861. It gained university status in 1992 and its present name in 2001. The main campus is in the heart of the city of Lincoln alongside the Brayford Pool.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('940a1726-859c-4338-886b-7a98779f0faa'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/University_of_Gloucestershire_logo.svg/500px-University_of_Gloucestershire_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,NULL,NULL,$q$The University of Gloucestershire is a public university based in Gloucestershire, England. It is located over four campuses; two in Cheltenham and two in Gloucester.
The university is the successor of a large number of merged, name-changed and reformed institutions of further and higher education.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f8c35a8a-f1a8-494f-9e4a-951fbf4623c7'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/8/8f/University_of_Wales%2C_Lampeter._-_geograph.org.uk_-_423417.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: RHYS  WILLIAMS, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Wales Trinity Saint David is a public university with campuses in Carmarthen, Swansea, Cardiff, Birmingham and London.
The university came into existence through the merger of the two oldest higher education institutions in Wales, the University of Wales, Lampeter and Trinity University College in 2010, under Lampeter's royal charter of 1828. In 2011, it was announced that the University of Wales would also merge into Trinity Saint David.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('05eb69e7-21dd-43c0-a30d-20cf349c46a6'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/University_of_Liverpool_Building.jpg/1280px-University_of_Liverpool_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: User:Chowells, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Liverpool is a public research university in Liverpool, England. Founded in 1881 as University College Liverpool and affiliated with Victoria University in 1884, it received a royal charter from King Edward VII in 1903, thereby attaining the authority to award degrees independently. The university holds and operates assets on the National Heritage List, such as the Liverpool Royal Infirmary, the Ness Botanic Gardens, and the Victoria Gallery & Museum.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('14a32f01-da3b-4ca2-adc0-aa728d19ff2e'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/University_of_Leicester_towers_2010.jpg/1280px-University_of_Leicester_towers_2010.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: NotFromUtrecht, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Leicester is a public research university based in Leicester, England. It was established as a university college in 1921. In 1957, the university's predecessor, University College, Leicester, gained university status by royal charter.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('da3b0516-be39-4d1b-a1da-8bae26376479'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/b/b9/HuddunimainmarqueRGB.gif?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: University Of Huddersfield, CC BY 3.0, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/4/43/Queensgate_Campus_Top.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: University Of Huddersfield, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Huddersfield is a public research university located in Huddersfield, West Yorkshire, England. It has been a University since 1992, but has its origins in a series of institutions dating back to the 19th century. It has made teaching quality a particular focus of its activities, winning the inaugural Higher Education Academy Global Teaching Excellence Award in 2017, and achieving a Teaching Excellence Framework Gold Award, in 2017  and 2023.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4d7be9d4-3e18-40df-99bc-8c6b5bc2e04c'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/York_St_John_University.jpg/1280px-York_St_John_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Robert Dawson, CC BY-SA 4.0, Wikimedia Commons$q$,$q$York St John University, often abbreviated to YSJ, is a public university located on a large urban campus in York, England. Established in 1841, it achieved university status in 2006 and in 2015 was given research degree awarding powers for PhD and other doctoral programmes.
It is one of several higher education institutions which have religious foundations and is part of the Cathedrals Group of Universities.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('9ceb568a-5e21-4809-a8a9-8aebfefb690c'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/1/17/Open_University_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: The Open University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/Robert_Hook_building_at_Open_University_Campus_in_Milton_Keynes%2C_spring_2013_%282%29.JPG/1280px-Robert_Hook_building_at_Open_University_Campus_in_Milton_Keynes%2C_spring_2013_%282%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chmee2, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Open University is a public research university and the largest university in the United Kingdom by number of students. The majority of the OU's undergraduate students are based in the United Kingdom and principally study off-campus; many of its courses can also be studied anywhere in the world. There are also a number of full-time postgraduate research students based on the 45 ha university campus at Walton Hall in Milton Keynes, Buckinghamshire, where they use the staff facilities for research, as well as more than 1,000 members of academic and research staff and over 2,500 administrative, operational and support staff.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d438a1a9-bb01-48da-9498-a21c94aa64cc'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/University_of_Essex_logo.svg/500px-University_of_Essex_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Essex, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/University_of_Essex_-_Albert_Sloman_Library.png/1280px-University_of_Essex_-_Albert_Sloman_Library.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Goosta, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Essex is a public research university in Essex, England. Established by royal charter in 1965, it is one of the original plate glass universities. The university comprises two campuses in the county, one in Loughton with its primary campus in Wivenhoe Park, Colchester.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('94818231-694c-4573-9223-01f1535f21c2'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/York_central_hall.jpg/1280px-York_central_hall.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Johnteslade at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$The University of York is a collegiate public research university in York, England. Established in 1963, the university has expanded to more than thirty departments and centres, covering a wide range of subjects.
South-east of the city of York, the university campus is about 500 acres in size.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('70cabf26-596b-46c2-9a8f-7742bbd9776c'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/School_of_Arts_-_UKC.JPG/1280px-School_of_Arts_-_UKC.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: St BC (talk), CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Kent is a university within the London and South East University Group in Kent, England. It was an independent university from 1965, when it was founded by royal charter, to 2026, when it merged with the University of Greenwich to form LASE. Following the merger, Kent became an academic division within LASE, operating under the branding of the University of Kent, while LASE's academic board became responsible for the admission of students, teaching and granting degrees. However, students apply to, are taught at, and receive degrees in the name of, the University of Kent.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('36de4a32-7308-4197-bab0-5a7d54d99e9d'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/LBU_entrance_cropped_2015_01.jpg/1280px-LBU_entrance_cropped_2015_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chemical Engineer, cropped by Blackcat, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Leeds Beckett University, formerly known as Leeds Metropolitan University and before that as Leeds Polytechnic, is a public university in Leeds, West Yorkshire, England. It has campuses in the city centre and Headingley. The university's origins can be traced to 1824, with the foundation of the Leeds Mechanics Institute.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('1fdba734-8ef7-4cae-997b-99b398b3f30f'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Senate_House_UoL.jpg/1280px-Senate_House_UoL.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: An Siarach at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$The University of London is a federal public research university in London, England, United Kingdom. The university was established by royal charter in 1836 as a degree-awarding examination board for students holding certificates from University College London, King's College London, and "other such institutions, corporate or unincorporated, as shall be established for the purpose of Education, whether within the Metropolis or elsewhere within our United Kingdom". It is one of three institutions to have claimed the title of the third-oldest university in England.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4dca123b-9db3-472f-b2dd-30458b913969'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Nottingham%2C_Trent_Building.jpg/1280px-Nottingham%2C_Trent_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Greentreepencil, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Nottingham is a public research university in Nottingham, England. It was founded as University College Nottingham in 1881, and was granted a royal charter as a university in 1948.
Nottingham's main campus, the Jubilee Campus and the main teaching hospital are located within the City of Nottingham, with a number of smaller campuses and sites elsewhere in Nottinghamshire and Derbyshire.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c8b0c546-d338-40d4-9907-e4013f50db34'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/University_for_the_Creative_Arts_%28UCA%29_logo.png/500px-University_for_the_Creative_Arts_%28UCA%29_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: UniCreativeArts, CC BY 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/University_for_the_Creative_Arts%2C_Farnham%2C_Courtyard_Entrance.jpg/1280px-University_for_the_Creative_Arts%2C_Farnham%2C_Courtyard_Entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: BabelStone, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University for the Creative Arts is a specialist art and design university in Southern England.
It was formed in 2005 as University College for the Creative Arts at Canterbury, Epsom, Farnham, Maidstone and Rochester when the Kent Institute of Art and Design was merged into the Surrey Institute of Art & Design, which already had degree-awarding status; both constituent schools had been formed by merging the local art schools, in Kent and Surrey respectively. It was granted university status in 2008, and the name changed to the present one.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('dd89831a-8897-4848-b322-ba8ac5c41429'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Arts_University_Plymouth.jpg/1280px-Arts_University_Plymouth.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Onlytruejames, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Arts University Plymouth is a public university located in Plymouth in South West England. The former Plymouth College of Art was officially granted university status in 2022. In April 2019 the specialist college was awarded taught degree awarding powers by the Quality Assurance Agency for Higher Education, granting the institution the authority to award and accredit its own BA degrees and Masters awards.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f02b428f-c2d4-41c1-a35d-c171b3d32155'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Northumbria_University_%28geograph_2248224%29.jpg/1280px-Northumbria_University_%28geograph_2248224%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Peter McDermott, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Northumbria at Newcastle, which operates as Northumbria University, is a public research university located in Newcastle upon Tyne, North East of England. It has been a university since 1992, but has its origins in the Rutherford College, founded in 1877.
Northumbria University is primarily based within City Campus located in Newcastle upon Tyne city centre and at Coach Lane campus on the outskirts of the city centre, London and Amsterdam.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('0a596cd2-3060-40dc-9d23-37022cfedb9f'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/University_of_Bradford_Richmond_24_April_2017_01.jpg/1280px-University_of_Bradford_Richmond_24_April_2017_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chemical Engineer, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Bradford is a public research university located in the city of Bradford, West Yorkshire, England. A plate glass university, it received its royal charter in 1966, making it the 40th university to be created in Britain, but can trace its origins back to the establishment of the industrial West Yorkshire town's Mechanics Institute in 1832. Known for its research, inclusivity and careers support for students, it has been named England's top university for social mobility five years in a row.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2f8ad330-6dc8-4e7e-a167-c4a0419a4df2'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/4/45/Canterbury_Christ_Church_University_-_geograph.org.uk_-_984484.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Nigel Chadwick, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Canterbury Christ Church University is a public research university located in Canterbury, Kent, England. Founded as a Church of England college for teacher training in 1962, it was granted university status in 2005.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c3be4dce-2e9c-4f88-b6d9-bddea073243d'::uuid,NULL,NULL,NULL,NULL,$q$Birmingham Newman University is a public university based in the suburb of Bartley Green in Birmingham, England. The university was founded in 1968 as Newman College of Higher Education. From 2008 to 2013, it was known as Newman University College, gaining full university status in 2013.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('92dcb85b-bbe8-4622-8f04-401d314c0aa8'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Cardiff_University_%28logo%29.svg/500px-Cardiff_University_%28logo%29.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Cardiff University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/4/44/Cardiff_University_main_building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Stan Zurek, Public domain, Wikimedia Commons$q$,$q$Cardiff University is a public research university in Cardiff, Wales. It was established in 1883 as the University College of South Wales and Monmouthshire and became a founding college of the University of Wales in 1893. It was renamed University College, Cardiff in 1972 and merged with the University of Wales Institute of Science and Technology in 1988 to become University of Wales College, Cardiff and then University of Wales, Cardiff in 1996.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('bf7f3aa8-1973-4e6b-937a-e58e675b94a5'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/4/41/St_Andrews_University_Classics_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of St Andrews is a public research university in the town of St Andrews in Scotland. It is the oldest of the four ancient universities of Scotland and, following the universities of Oxford and Cambridge, the third-oldest university in the English-speaking world. St Andrews was founded in 1413 when the Antipope Benedict XIII issued a papal bull to a small founding group of Augustinian clergy.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2f72d4ab-31a5-4553-8690-ccf1e09ede1e'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/6/6d/Skiddaw_Building%2C_University_of_Cumbria_-_geograph.org.uk_-_715574.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Rose and Trev Clough, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Cumbria is a public university in Cumbria, with its headquarters in Carlisle and other major campuses in Lancaster, Ambleside, and London. It has roots extending back to the Society for the Encouragement of Fine Arts, established in 1822, and the teacher training college established by Charlotte Mason in the 1890s. It opened its doors in 2007 as a university.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('cb36622d-5e57-4ebd-ad31-a25574c4e9e8'::uuid,NULL,NULL,NULL,NULL,$q$The University of Bedfordshire is a public research university with campuses in Bedfordshire and Buckinghamshire, England. The university has roots in further and higher education from 1882: it gained university status in 1993 as the University of Luton. The university changed its name to the University of Bedfordshire in 2006, following the merger of the University of Luton with the Bedford campus of De Montfort University.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ad798243-2d5f-4884-ae45-5d9d2f402005'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Keele_University_Library.jpg/1280px-Keele_University_Library.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jonathan Hutchins, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Keele University is a public research university in Keele, Staffordshire, England. Originally established in 1949 as the University College of North Staffordshire, it received university status through a Royal Charter in 1962, becoming the University of Keele. The university pioneered the UK's dual honours degree system, offering students the chance to study two subjects together.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('137988d7-8611-4bf6-9a45-ca409ce67ac8'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/4/4e/Goldsmithsnew.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: GUL, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/3/37/Goldsmiths_Main_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Alex Blandford, CC BY 2.0, Wikimedia Commons$q$,$q$Goldsmiths, University of London, formerly Goldsmiths' College, University of London, is a constituent research university of the University of London. It was originally founded in 1891 as The Goldsmiths' Technical and Recreative Institute by the Worshipful Company of Goldsmiths in New Cross, London. It was renamed Goldsmiths' College after being acquired by the University of London in 1904, and specialises in the arts, design, computing, humanities and social sciences.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('85be42b0-0357-4d7a-a226-2f3666bdff91'::uuid,NULL,NULL,NULL,NULL,$q$The University of Chichester is a public university located in West Sussex, England, which became a university in 2005. Campuses are based in the city of Chichester and the nearby coastal resort of Bognor Regis and an associate campus for commercial music on the Isle of Wight.
The University of Chichester has 14 departments, with specialisms including Humanities, Sport, Musical Theatre, Acting and Education.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('3825c081-38c9-4e9f-b594-dd4c06621249'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Kingston_University_logo.svg/500px-Kingston_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: The original uploader was Sakurambo at English Wikipedia., Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/8/8e/Knights_Park_Campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Public domain, Wikimedia Commons$q$,$q$Kingston University London is a public research university located within the Royal Borough of Kingston upon Thames, in South West London, England. Its roots go back to the Kingston Technical Institute, founded in 1899. It received university status in 1992, before which the institution was known as Kingston Polytechnic.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('20931b39-41df-4c17-834e-cffcc3f71e23'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/b/ba/Middlesex_University_Hendon_Campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Steve Cadman (stevecadman), CC BY-SA 2.0 uk, Wikimedia Commons$q$,$q$Middlesex University, branded as Middlesex University London, is a public research university based in Hendon, northwest London, England. The university also has campuses in Dubai and Mauritius. The university was in the historic county of Middlesex.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('99ebb4ec-bc17-45b4-8efa-a02310f51efa'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/The_Shield_of_Falmouth_University.png/1280px-The_Shield_of_Falmouth_University.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Falunioff, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Falmouth University is a specialist public university for the creative industries based in Falmouth and Penryn in Cornwall, UK. Founded as Falmouth School of Art in 1902, it was later known as Falmouth College of Art and Design and then Falmouth College of Arts until 2012, when the university college was officially granted full university status by the Privy Council.
The university is located across two campuses, in the towns of Penryn and Falmouth. Penryn Campus, near the town of Penryn, is the larger of its two campuses, which it operates in partnership with the University of Exeter.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2c488b63-d6f8-4559-9f19-eba5506931af'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/6/6a/Logo_colour_204px.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: The original uploader was Nandana1981 at English Wikipedia., Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/1/15/Oxford_brookes_headington_hill.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Donegalscott (talk), CC BY 1.0, Wikimedia Commons$q$,$q$Oxford Brookes University is a public university in Oxford, England. It is a new university, having received university status through the Further and Higher Education Act 1992. The university was named after its first principal, John Henry Brookes, who played a major role in the development of the institution.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('fd0aae89-3a9a-4b50-b2b7-cbc265679516'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/c/cc/Royalvetcoll.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Stephen McKay, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The Royal Veterinary College is a veterinary school located in London and a member institution of the federal University of London. The RVC was founded in 1791 and joined the University of London in 1949. It is the oldest and largest veterinary school in the United Kingdom, and one of only 12 in the country where students can study to become a vet.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('46099416-2b93-4080-83e2-92a62c95824c'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/UniSSoM.jpg/1280px-UniSSoM.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Mark Boyce, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Surrey is a public research university in Guildford, Surrey, England. The university received its royal charter in 1966, along with a number of other institutions following recommendations in the Robbins Report. The institution was previously known as Battersea College of Technology and was in Battersea Park, London.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d4454705-0bc2-47c8-932f-a6ecacfaee4a'::uuid,NULL,NULL,NULL,NULL,$q$University College Birmingham is a university in Birmingham, England. It was awarded full university status in 2012 along with Newman University. It is not a member of Universities UK. Students were asked to rate their university experience for the 2024 Whatuni Student Choice Awards, considering what shaped their time at university, and it came out on top in the West Midlands for student support.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('5d9e6649-6ab9-4096-95f0-591649f2c6fc'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Arts_University_Bournemouth_campus%2C_library_%26_MoDiP.jpg/1280px-Arts_University_Bournemouth_campus%2C_library_%26_MoDiP.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: proficient-moose, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Arts University Bournemouth is a public university in Poole, England, specialising in art, architecture, film, performance, and design. Established in 1880, the university has been ranked Silver and Gold by the Teaching Excellence Framework in 2017, and was rated Outstanding by Ofsted, having retained this highest ranking since 2018. The Bournemouth Film School, a division of the university, was established in 1963 and is a full member of CILECT.
AUB alumni include BAFTA and Academy Award winning filmmakers, and a Turner Prize recipient.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('7ea3eb59-2d9e-4ddf-bc31-8417817f36bf'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Lancaster_University_Courtyard.JPG/1280px-Lancaster_University_Courtyard.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Christoph Michels, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Lancaster University is a collegiate public research university in Lancaster, Lancashire, England. The university was established in 1964 by royal charter, as one of several new universities created in the 1960s.
The university was initially based in St Leonard's Gate in the city centre, before starting a move in 1967 to a purpose-built campus located on 300 acres at Bailrigg, 4 km to the south of the city.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('5aa969fc-1862-4666-a720-7de98a1771c5'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/c/c6/University_of_Chester_-_geograph.org.uk_-_1331802.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Dennis Turner, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Chester is a public university located in Chester, England. The university originated as the first purpose-built teacher training college in the UK. As a university, it now occupies seven campus sites in and around Chester, one in Warrington, and a University Centre in Birkenhead. It offers a range of foundation, undergraduate and postgraduate courses, as well as undertaking academic research.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e5852981-8d2d-4dc6-8d26-26a843ad3ed1'::uuid,NULL,NULL,NULL,NULL,$q$The University of Winchester is a public research university based in the city of Winchester, Hampshire, England. The university has origins tracing back to 1840 as a teacher training college, but was established in 2005.
Winchester University is a member of The Cathedrals Group, an association of universities and university colleges in the United Kingdom.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('08cad281-3c20-4811-a4c0-df538a979164'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/5/56/Bolton_University_-_Deane_campus_-_geograph.org.uk_-_109397.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Margaret Clough, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Greater Manchester is a public university in Bolton, Greater Manchester in England. It was known as the University of Bolton from 2005 until 2024. The university is commonly referred to as a 'post-92' institution, which is a reference to the Further and Higher Education Act 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('08e682ed-8f53-48d5-98af-c0d0bfc7a7ca'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/UWIC_Llandaff_Cardiff.JPG/1280px-UWIC_Llandaff_Cardiff.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Welshleprechaun, Public domain, Wikimedia Commons$q$,$q$Cardiff Metropolitan University is a public university located in Cardiff, Wales. It was formerly known as the University of Wales Institute, Cardiff which was established in 1996.
The university offers degree courses in a variety of disciplines.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('39412e88-a50b-4276-9f39-3edafa39aa61'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/1/13/Manchester_School_of_Art_Geograph_3735342.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: David Dixon, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Manchester Metropolitan University is a public university in Manchester, England. The university's predecessor, Manchester Polytechnic, gained university status in 1992. The university has 44,000 students and over 5,100 members of staff.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f38630ab-9064-4e5b-afe7-3ef9c993db2c'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/3/31/CollegeBuilding.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Normal4norfolk at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$City St George's, University of London is a public research university in London, England, and a member institution of the University of London. Founded in 1894 as the Northampton Institute, it officially became a university when the City University was created by royal charter in 1966. The Inns of Court School of Law, which merged with City in 2001, was established in 1852.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('89e22c5f-e246-4816-87e8-d61fdb064af4'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Shield_of_the_University_of_Sheffield.svg/500px-Shield_of_the_University_of_Sheffield.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Sir_Frederick_Mappin_Building.jpg/1280px-Sir_Frederick_Mappin_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Paolo Margari from Sheffield, United Kingdom / Italy, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Sheffield is a public research university in Sheffield, South Yorkshire, England. Its history traces back to the foundation of Sheffield Medical School in 1828, Firth College in 1879 and Sheffield Technical School in 1884. The University College of Sheffield was subsequently formed by the amalgamation of the three institutions in 1897.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('48ea74c8-a747-4f8e-a065-25fdfb2bc532'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/University_of_Cambridge_logo.png/500px-University_of_Cambridge_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Dm980cam, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/St_John%27s_College_Second_Court%2C_Cambridge%2C_UK_-_Diliff.jpg/1280px-St_John%27s_College_Second_Court%2C_Cambridge%2C_UK_-_Diliff.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Diliff, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Cambridge is a collegiate public research university in Cambridge, England. Founded in 1209, the University of Cambridge is the second-oldest university in the English-speaking world and the world's third-oldest university in continuous operation. The university's founding followed the arrival of scholars who left the University of Oxford for Cambridge after a dispute with local townspeople.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('903e25ca-e816-4b7d-95e9-a2ed711f1a94'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/University_of_Reading_arms.svg/500px-University_of_Reading_arms.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Hogweard, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/3/3a/The_University_of_Reading.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Andrew Smith, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Reading is a public research university in Reading, Berkshire, England. It was founded in 1892 as the University Extension College, Reading, an extension college of Christ Church, Oxford, and became University College, Reading in 1902. The institution became a university with the power to grant its own degrees in 1926 by royal charter from King George V, and was the only university to receive such a charter between the two world wars.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('116cb664-56cc-44ef-b914-84901da71147'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Exepos%C3%A9_Logo_2012_-_present_%28cropped%29.jpg/500px-Exepos%C3%A9_Logo_2012_-_present_%28cropped%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Cryek, CC BY-SA 3.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/University_of_Exeter_Clock_tower.jpg/1280px-University_of_Exeter_Clock_tower.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Myself, Benjamin Evans, Public domain, Wikimedia Commons$q$,$q$The University of Exeter is a public research university in the West Country of England, with its main campus in Exeter, Devon. Its predecessor institutions, St Luke's College, Exeter School of Science, Exeter School of Art, and the Camborne School of Mines were established in 1838, 1855, 1863, and 1888 respectively. These institutions formed the University of Exeter when it received its royal charter in 1955.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e31eb188-42d1-47b1-baa3-1a539cd7f7d4'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/e/e7/University_of_Salford_Logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: University of Salford, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/University_of_Salford.jpg/1280px-University_of_Salford.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Paul Stainthorp, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Salford is a public research university located in Salford, Greater Manchester, England, 1 mile west of Manchester city centre. The Royal Technical Institute, Salford, which opened in 1896, became a College of Advanced Technology in 1956 and gained university status in 1967, following the Robbins Report into higher education.
It has 26,030 students and is in 160 acres of parkland on the banks of the River Irwell.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('0dcd0365-b6b8-4b31-9d06-da7688de9fb0'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/4/40/St_Mary%27s_University_College_-_geograph.org.uk_-_1178912.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Colin Smith, CC BY-SA 2.0, Wikimedia Commons$q$,$q$St Mary's University is a public university in Strawberry Hill, Twickenham, in the London Borough of Richmond upon Thames. Established in 1850, it is the oldest Catholic university in the United Kingdom. The university received full university status in 2014 and has since expanded its academic portfolio, particularly in teacher education, sport science, health, and the humanities.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('232da8e0-4beb-4cff-beda-e7ef293639cc'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/RoyalAg2.jpg/1280px-RoyalAg2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jongleur100, Public domain, Wikimedia Commons$q$,$q$The Royal Agricultural University, formerly the Royal Agricultural College, is a public university in Cirencester, Gloucestershire, England. Established in 1845, it was the first agricultural college in the English-speaking world.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('aa972233-a746-48f5-8c82-a7db56b7dca1'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Teesside_University%27s_Phoenix_Building.JPG/1280px-Teesside_University%27s_Phoenix_Building.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: LTees, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Teesside University is a public university with its main campus in Middlesbrough, North Yorkshire in North East England. It was officially opened as Constantine Technical College in 1930, before becoming a polytechnic in 1969, and finally granted university status in 1992 by the Privy Council.
The university has over 22,500 students studying in the UK, according to the 2021/22 HESA student record.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('26e1f3b5-b007-4ef4-8b63-381c2fb3a040'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Logo_of_University_of_South_Wales.svg/500px-Logo_of_University_of_South_Wales.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of South Wales, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/University_of_South_Wales%2C_Newport_city_centre_campus.jpg/1280px-University_of_South_Wales%2C_Newport_city_centre_campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Pwimageglow, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of South Wales is a public university in Wales, with campuses in Cardiff, Newport and Pontypridd. It was formed on 11 April 2013 from the merger of the University of Glamorgan and the University of Wales, Newport. The university is the second largest university in Wales in terms of its student numbers, and offers over 300 undergraduate and postgraduate courses.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a027ce5a-c15c-4860-be00-bf1519498d98'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/University_of_the_West_of_Scotland_Logo.svg/500px-University_of_the_West_of_Scotland_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of the West of Scotland, Public domain, Wikimedia Commons$q$,NULL,NULL,$q$The University of the West of Scotland, formerly the University of Paisley, is a public university with four campuses in south-western Scotland, in the towns of Paisley, Blantyre, Dumfries and Ayr, as well as a campus in London, England. The present institution dates from August 2007, following the merger of the University of Paisley with Bell College, Hamilton. It can trace its roots to the late 19th century, and has undergone numerous name changes and mergers over the last century, reflecting its gradual expansion throughout the west of Scotland region.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e4397bda-a1a0-4c7a-8716-138fecd42494'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/3/3b/University_of_Wolverhampton_-_geograph.org.uk_-_396324.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Gordon Griffiths, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Wolverhampton is a public university in Wolverhampton, England, located on four campuses across the West Midlands, Shropshire and Staffordshire. Originally founded in 1827 as the Wolverhampton Tradesmen's and Mechanics' Institute, the university was subject to a series of merges,  incorporations, and expansions with other local colleges, one of which occurred under the supervision of Prince George, Duke of Kent.
The university has four faculties comprising eighteen schools and institutes.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('51d90971-32d3-45e8-b3ce-ec0d46255835'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/CU_Coventry.png/500px-CU_Coventry.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ciaran McCormick, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Coventry_University.jpeg/1280px-Coventry_University.jpeg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$CC BY 2.5, Wikimedia Commons$q$,$q$Coventry University is a public research university in Coventry, England. The origins of Coventry University can be linked to the Coventry School of Design in 1843. It was known as Lanchester Polytechnic from 1970 until 1987, and then as Coventry Polytechnic until it gained university status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ba192f08-58a1-4e38-a2f7-9fe75ebf0cbf'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/c/ca/University_of_Roehampton_logo.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Product1977, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Grove_House%2C_Roehampton_-_Diliff.jpg/1280px-Grove_House%2C_Roehampton_-_Diliff.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Diliff, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Roehampton is a public research university in Roehampton, London. Founded as the Roehampton Institute of Higher Education, the university was established by four institutions, founded in the 19th century, which today make up the university's constituent colleges: Digby Stuart College, Froebel College, Southlands College and Whitelands College.
Between 2000 and 2004, Roehampton, together with the University of Surrey, partnered as the Federal University of Surrey.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('671b712b-63d7-45f0-8301-4b6057370923'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/CampusofUCLanCyprus.jpg/1280px-CampusofUCLanCyprus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: UCLanCyprus, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Lancashire is a public university based in the city of Preston, Lancashire, England. It has its roots in The Institution For The Diffusion Of Useful Knowledge, founded in 1828. Previously known as the University of Central Lancashire, Harris Art College, Preston Polytechnic and Lancashire Polytechnic, in 1992 it was granted university status by the Privy Council.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e6e62e9e-2254-40f0-816f-333727cdf6c5'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Anglia_Ruskin_Cambridge_Main%2C_28_Sep%2C_2012.jpg/1280px-Anglia_Ruskin_Cambridge_Main%2C_28_Sep%2C_2012.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Mohammed Tawsif Salam, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Anglia Ruskin University is a public research university in the region of East Anglia, United Kingdom. Its origins date back to the Cambridge School of Art, founded in 1858 by William John Beamont, a Fellow of Trinity College at the University of Cambridge. The institution became a university in 1992 and was renamed after John Ruskin, the Oxford University professor and author, in 2005.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2a60932d-50f8-4cce-86b3-27f3bd854ac2'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Northwesternhall.JPG/1280px-Northwesternhall.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Cxnbs32, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Liverpool John Moores University is a public research university in the city of Liverpool, United Kingdom. The university can trace its origins to the Liverpool Mechanics' School of Arts, established in 1823. This later merged to become Liverpool Polytechnic.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('10c2ca8c-162f-4a4a-8ebf-68beee83feca'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/b/b5/Aston_University_Logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Copyrighted official logo for Aston University, UK., Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/Aston_Uni_Lakeside_01.JPG/1280px-Aston_Uni_Lakeside_01.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chemical Engineer, Public domain, Wikimedia Commons$q$,$q$Aston University is a public university situated in the city centre of Birmingham, England. Aston began as the Birmingham Municipal Technical School in 1895, evolving into the UK's first college of advanced technology in 1956. Aston University received its royal charter from Queen Elizabeth II on 22 April 1966.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('43354e7a-e947-4a4b-9109-6282a1472790'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Queen%27s_University_Belfast_arms.svg/500px-Queen%27s_University_Belfast_arms.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$CC BY-SA 3.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Lanyon_Building%2C_Queen%27s_University%2C_Belfast.jpg/1280px-Lanyon_Building%2C_Queen%27s_University%2C_Belfast.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Nick Birse, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The Queen's University of Belfast, commonly known as Queen's University Belfast, is a public research university in Belfast, Northern Ireland. The university received its charter in 1845 as part of the Queen's University of Ireland and opened four years later, together with University of Galway and University College Cork.
Queen's offers approximately 300 academic degree programmes at various levels.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ae23a315-1132-4709-a125-80d473499cfc'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/University_of_Hertfordshire_Logo.svg/500px-University_of_Hertfordshire_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Hertfordshire, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/UHCollegeLaneCampus.jpg/1280px-UHCollegeLaneCampus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: en:User:Jknabe and de:User:Jknabe, Public domain, Wikimedia Commons$q$,$q$The University of Hertfordshire is a public research university in Hertfordshire, United Kingdom. It is based primarily in Hatfield, Hertfordshire. Its antecedent institution, Hatfield Technical College, was founded in 1948 and was identified as one of 25 Colleges of Technology in the United Kingdom in 1959.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('929be3d6-a532-428d-8ae9-73f6e825fc63'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/4/42/New_Logo_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: BenSalem1, CC BY-SA 3.0, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/6/6c/The_Wilfred_Brown_Building_at_Brunel_University_-_geograph.org.uk_-_1518813.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Basher Eyre, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Brunel University of London is a public research university located in the Uxbridge area of London, England. It is named after Isambard Kingdom Brunel, a Victorian engineer and pioneer of the Industrial Revolution. It became a university in June 1966, when Brunel College of Advanced Technology was awarded a royal charter and became Brunel University; it is sometimes considered a plate glass university.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('84d64601-96fa-452e-825e-f295d2240b4e'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/University_of_Ulster_logo.svg/500px-University_of_Ulster_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/University_of_Ulster%2C_Belfast_Campus%2C_July_2010_%2807%29.JPG/1280px-University_of_Ulster%2C_Belfast_Campus%2C_July_2010_%2807%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ardfern, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Ulster University, legally the University of Ulster, is a multi-campus public research university located in Northern Ireland. It is often referred to informally and unofficially as Ulster, or by the abbreviation UU. It is the largest university in Northern Ireland and the second-largest university on the island of Ireland, after the federal National University of Ireland.
Established in 1865 as Magee College, the college took its modern form in 1984 after the merger of the New University of Ulster established in 1968, and Ulster Polytechnic, incorporating its four Northern Irish campuses under the University of Ulster banner.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('50603186-fe0f-4bc8-8d93-38cfc7d0eb54'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/b/b7/Craiglockhart.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Edinburgh Napier University, Public domain, Wikimedia Commons$q$,$q$Edinburgh Napier University is a public university in Edinburgh, Scotland. Napier Technical College, the predecessor of the university, was founded in 1964, taking its name from 16th-century Scottish mathematician and philosopher John Napier. The technical college was inaugurated as a university in 1992 by Lord Douglas-Hamilton, becoming Napier University.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('bfabc276-11ff-4d07-b003-40ab7fbe27f2'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/d/d7/University_of_Plymouth_Arts_Block.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Tony Atkin, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Plymouth is a public research university based predominantly in Plymouth, England, where the main campus is located, but the university has campuses and affiliated colleges across South West England. With 18,410 students, it is the 57th largest in the United Kingdom by total number of students.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('db9eafae-1e59-46a1-a454-b5d99c453c6f'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Sheffield_Hallam_University_logo.svg/500px-Sheffield_Hallam_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Sheffield Hallam University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/2/2f/SHU_buildings.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: St BC at English Wikipedia, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Sheffield Hallam University is a public research university in Sheffield, South Yorkshire, England. The university is based on two sites; the City Campus is located in the city centre near Sheffield railway station, while the Collegiate Crescent Campus is about two miles away in the Broomhall Estate off Ecclesall Road in south-west Sheffield. A third campus at Brent Cross Town in the London Borough of Barnet is expected to open for the 2025–2026 academic year.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('7e6073de-bc9b-4cce-b07e-449822283df2'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/University_of_Westminster_Logo.svg/500px-University_of_Westminster_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Westminster, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/b/b8/University_of_Westminster%2C_Harrow_Campus_-_geograph.org.uk_-_98048.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: David Hawgood, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Westminster is a public university based in London, United Kingdom. Founded in 1838 as the Royal Polytechnic Institution, it was the first polytechnic to open in London. The Polytechnic formally received a Royal charter in August 1839, and became the University of Westminster in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('1c9af7e8-0fe3-4067-8a71-4fff11458c0a'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/University_of_Brighton_logo.svg/500px-University_of_Brighton_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Brighton, Public domain, Wikimedia Commons$q$,NULL,NULL,$q$The University of Brighton is a public university based in Brighton on the south coast of England. Its roots can be traced back to 1858 when the Brighton School of Art was opened in the Royal Pavilion. It achieved university status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f50d2f6b-5ee4-482b-9c0d-1f1f9ea60cb1'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Bath_Spa_University_logo.svg/500px-Bath_Spa_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Bath Spa University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/0/03/Bath-spa-university-feature-image-1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Bath Spa University, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Bath Spa University is a public university in Bath, England, with its main campus at Newton Park, about 3+1⁄2 miles west of the centre of the city. The university has other campuses in the city of Bath and London, as well as a site at Corsham Court in Wiltshire.
The institution gained full university status in August 2005, having been previously known as Bath College of Higher Education, and later Bath Spa University College.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('5028aad2-ef93-49fc-a5b1-d912b65e7c00'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/St_Katherine%27s_College%2C_Liverpool-2.jpg/1280px-St_Katherine%27s_College%2C_Liverpool-2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Rodhullandemu, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Liverpool Hope University is a public university with campuses in Liverpool, England. ‌The university grew out of three teacher training colleges: Saint Katharine's College, Notre Dame College and Christ's College. Uniquely in European higher education, the university is ecumenical, with Saint Katharine's College being Anglican and Notre Dame and Christ's Colleges being Catholic.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4b1603eb-750f-41f4-b89b-d26f9cb406e4'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/University_of_Southampton_Logo.svg/500px-University_of_Southampton_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Southampton, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/HartleyLibraryFront.JPG/1280px-HartleyLibraryFront.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Iamtheabelman, CC BY 3.0, Wikimedia Commons$q$,$q$The University of Southampton is a public research university in Southampton, England. Southampton is a founding member of the Russell Group of research-intensive universities in the United Kingdom.
The university has seven campuses.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('41dd8aa0-4acd-46fd-98b5-81b3f0bd5e5b'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Southampton-Solent-University-logo.svg/500px-Southampton-Solent-University-logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Southampton Solent University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/e/e3/Eingang-SSU.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Paul Heimann (GoG at German Wikipedia), Public domain, Wikimedia Commons$q$,$q$Southampton Solent University is a public university based in Southampton, Hampshire, England. It has approximately 10,500 students. Its main campus is located on East Park Terrace near the city centre and the maritime hub of Southampton.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('02b6ec3a-f95a-404f-bc20-8d9a4c93c97c'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/a/a4/University_of_Stirling_-_Dormitories.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Roger Wollstadt from Sarasota, Florida, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Stirling is a public university in Stirling, Scotland, founded by a royal charter in 1967. It is located in the Central Belt of Scotland, built within the walled Airthrey Castle estate. 
The university campus is approximately 360 acres in size, incorporating the Stirling University Innovation Park and the Dementia Centre.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d162b3af-a079-4915-979e-af94a39e5433'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/University_of_Portsmouth_Logo.png/500px-University_of_Portsmouth_Logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Critical Hippo, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/University_of_Portsmouth_Dennis_Sciama_building.JPG/1280px-University_of_Portsmouth_Dennis_Sciama_building.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Editor5807, CC BY 3.0, Wikimedia Commons$q$,$q$The University of Portsmouth is a public university in Portsmouth, England. Its institutional origins trace back to 1870 with the establishment of the Portsmouth and Gosport School of Science and Art. Over the subsequent decades, the institution underwent a series of organisational transformations, becoming Portsmouth Polytechnic in 1969 before gaining university status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('6ea0cd23-f96f-47fe-b160-c2a1b73d0263'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/5/5a/Heriot_Watt_University_Scottish_Borders_Campus_-_geograph.org.uk_-_210840.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Walter Baxter, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Heriot-Watt University is a public research university based in Edinburgh, Scotland. It was established in 1821 as the School of Arts of Edinburgh, the world's first mechanics' institute, and was subsequently granted university status by royal charter in 1966. It is the eighth-oldest higher education institution in the United Kingdom.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('18e6fd83-1046-40af-8359-010b114e89bc'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Bournemouth_Uni_entrance.jpg/1280px-Bournemouth_Uni_entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Tom Morris, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Bournemouth University is a public university in Bournemouth, England, with its main campus situated in neighbouring Poole. The university was founded in 1992; however, the origins of its predecessor date back to the early 1900s.
The university currently has over 17,000 students, including over 3,000 international students.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ec2db1ae-597f-42d1-b3a8-f73e0525be86'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Queen_Mary_University_of_London_coat_of_arms.svg/500px-Queen_Mary_University_of_London_coat_of_arms.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: AlexD, CC BY-SA 3.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Queens%27_Building_%282899476115%29.jpg/1280px-Queens%27_Building_%282899476115%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ewan Munro from London, UK, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Queen Mary University of London is a public research university in London, England. It is a member institution of the federal University of London. Queen Mary is a member of the Russell Group of research-intensive British universities, the Association of Commonwealth Universities and Universities UK.
Today, Queen Mary has six campuses across East and Central London in Mile End, Whitechapel, Charterhouse Square, Ilford, Lincoln's Inn Fields and West Smithfield, as well as an international presence in China, France, Greece and Malta.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('1ac08b8b-eb7d-4d56-8490-68fb3580f7e1'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/UCL_Crest.svg/500px-UCL_Crest.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: AlexD, new version by Gnesener1900, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/Wilkins_Building_1%2C_UCL%2C_London_-_Diliff.jpg/1280px-Wilkins_Building_1%2C_UCL%2C_London_-_Diliff.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Diliff, CC BY-SA 3.0, Wikimedia Commons$q$,$q$University College London, which operates as UCL, is a public research university in London, England. It is a member institution of the federal University of London, and is the second-largest university in the United Kingdom by total enrolment and the largest by postgraduate enrolment.
Established in 1826 as London University by founders who were inspired by the radical ideas of Jeremy Bentham, UCL was the first university institution to be established in London, and the first in England to be entirely secular and to admit students regardless of their religion.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c1af869a-6bf8-4d05-94dc-96855cd531e8'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/2/29/University_of_Strathclyde_Campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Flickr User StrathclydeGuy, CC BY 2.0, Wikimedia Commons$q$,$q$The University of Strathclyde is a public research university located in Glasgow, Scotland. Founded in 1796 as the Andersonian Institute, it is Glasgow's second-oldest university, having received its royal charter in 1964 as the first technological university in the United Kingdom. Taking its name from the historic Kingdom of Strathclyde, its combined enrolment of 25,000 undergraduate and graduate students ranks it Scotland's third-largest university, drawn with its staff from over 100 countries.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4bfd381e-8ae5-4747-bc35-b4934098e585'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Parkinson_Building%2C_Leeds_University%2C_England-12Sept2010.jpg/1280px-Parkinson_Building%2C_Leeds_University%2C_England-12Sept2010.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Tim Green from Bradford, CC BY 2.0, Wikimedia Commons$q$,$q$The University of Leeds is a public research university in Leeds, West Yorkshire, England. It was established in 1874 as the Yorkshire College of Science. In 1884, it merged with the Leeds School of Medicine and was renamed Yorkshire College.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('5293886c-157c-4620-a66b-ff5b1cddf859'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Queen_Margaret_University_main_building.jpg/1280px-Queen_Margaret_University_main_building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Stuart Caie from Edinburgh, Scotland, CC BY 2.0, Wikimedia Commons$q$,$q$Queen Margaret University is a public university in Musselburgh, East Lothian, Scotland. It is named after Saint Margaret, Queen consort of Alba. 
The university can trace its origins to the Edinburgh School of Cookery and Domestic Science, founded in 1875.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4e1e7b86-b62e-4c64-aec2-ac2e8ea51efc'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/Leeds_Trinity_University_%28geograph_3395276%29.jpg/1280px-Leeds_Trinity_University_%28geograph_3395276%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: John Slater, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Leeds Trinity University is a public university in Horsforth, Leeds, West Yorkshire, England. Originally established to provide qualified teachers to Catholic schools, it gradually expanded and now offers foundation, undergraduate, and postgraduate degrees in a range of humanities and social sciences.
Previously known as Leeds Trinity & All Saints, the institution became a university college in 2009 after gaining the right to award its own degrees, and was granted full university status in December 2012.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f2284fd4-027c-4164-b37e-d2235072aefe'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Staffordshire_University_Logo.svg/500px-Staffordshire_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Staffordshire University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/f/fe/Staffordshire_University%2C_College_Road%2C_Stoke_-_geograph.org.uk_-_332924.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Steven Birks, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Staffordshire is a public research university in Staffordshire, England. It has its main campus in Stoke-on-Trent and two other campuses in Stafford, and London.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ac3aaad3-4944-4672-91c7-43e843c63756'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Buckinghamshire_New_University.jpg/500px-Buckinghamshire_New_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Buckinghamshire New University, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/Gateway_building%2C_Buckinghamshire_New_University%2C_High_Wycombe%2C_Buckinghamshire_-_July_2026_-_01.jpg/1280px-Gateway_building%2C_Buckinghamshire_New_University%2C_High_Wycombe%2C_Buckinghamshire_-_July_2026_-_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Mertbiol, CC0, Wikimedia Commons$q$,$q$Bucks New University, is a public university in Buckinghamshire, England, with campuses in High Wycombe, Aylesbury, Uxbridge and Great Missenden. The institution dates from 1891, when it was founded as the School of Science and Art, and has since been known as Wycombe Technical Institute, High Wycombe College of Technology and Art and the Buckinghamshire College of Higher Education. It was a university college from 1999 until 2007, when its application for university status was accepted.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a4a3431f-ef33-4eac-8caf-f85c816f28b7'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Kcl-logo.svg/500px-Kcl-logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: reviczky, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/7/70/Strand102.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Flaming Ferrari (talk), Public domain, Wikimedia Commons$q$,$q$King's College London is a public research university in London, England. King's was established by royal charter in 1829 under the patronage of King George IV and the Duke of Wellington. In 1836, King's became one of the two founding colleges of the University of London.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('1cf18cd2-2cad-4afb-8f56-1b8e7b4d3522'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Wrexham_Glynd%C5%B5r_University_Logo.svg/500px-Wrexham_Glynd%C5%B5r_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Wrexham Glyndŵr University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/b/bc/Wrexham_Glyndwr_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Geoff Evans, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Wrexham University is a public university in the north-east of Wales, with campuses in Wrexham, Northop and St Asaph. It offers both undergraduate and postgraduate degrees, as well as professional courses. The university had 6,045 students in 2024/25.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d5982cd4-0fb3-4fa1-81ee-664adaa912c6'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/Shield_of_Loughborough_University.svg/500px-Shield_of_Loughborough_University.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Nil pat13, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/Loughborough_University_Entrance.jpg/1280px-Loughborough_University_Entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chick0nPTCG, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Loughborough University is a public research university in the market town of Loughborough, Leicestershire, England. It has been a university since 1966, but it dates back to 1909, when Loughborough Technical Institute was founded. In March 2013, the university announced it had bought the former broadcast centre at the Queen Elizabeth Olympic Park as a second campus.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('de08453b-50a7-4038-a357-c890ad821fb2'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/University_of_the_Arts_London%2C_Central_Services_Entrance.jpg/1280px-University_of_the_Arts_London%2C_Central_Services_Entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ualwebsupport, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of the Arts London is a public collegiate university in London, England, United Kingdom. It specialises in the arts, design, fashion, and the performing arts. The university is a federation of six arts colleges: Camberwell College of Arts, Central Saint Martins, Chelsea College of Arts, the London College of Communication, the London College of Fashion, and Wimbledon College of Arts.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a38c2aea-79f7-4dbc-b92c-21ce5c59cb51'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/6/67/University_College_of_the_Arts%2C_Duke_St_-_geograph.org.uk_-_1398450.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Nigel Chadwick, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The Norwich University of the Arts is a public university in Norwich, Norfolk, United Kingdom that specialises in art, design, media, architecture and performance. It was founded as Norwich School of Design in 1845 and has a long history of arts education. It gained full university status in 2013.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c51b7314-d316-4d22-ad45-578aa26d0447'::uuid,NULL,NULL,$q$https://upload.wikimedia.org/wikipedia/commons/7/7b/Leeds_College_of_Art_and_Design_-_geograph.org.uk_-_385408.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Betty Longbottom, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Leeds Arts University is a specialist arts further and higher education institution, based in the city of Leeds, West Yorkshire, England, with a main campus opposite the University of Leeds.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c31825d7-efe2-440c-a94e-7a92cd6b57de'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/United_Kingdom_-_England_-_London_-_Greenwich_-_Old_Royal_Naval_College.jpg/1280px-United_Kingdom_-_England_-_London_-_Greenwich_-_Old_Royal_Naval_College.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: C. G. P. Grey, CC BY 3.0, Wikimedia Commons$q$,$q$The University of Greenwich is a university within the London and South East University Group in Greenwich, England. It was an independent university from 1992 to 2026, when it merged with the University of Kent to form LASE. Following the merger, Greenwich became an academic division within LASE, operating under the branding of the University of Greenwich, while LASE's academic board became responsible for the admission of students, teaching and granting degrees. However, students apply to, are taught at, and receive degrees in the name of, the University of Greenwich.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a9d3f1d2-a69d-43ff-a540-2fba36a9da47'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Bay_Campus_Accommodation.jpg/1280px-Bay_Campus_Accommodation.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Swanseauni, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Swansea University is a public research university located in Swansea, Wales. It was established as University College of Swansea in 1920, as the fourth college of the University of Wales. In 1996, it changed its name to the University of Wales Swansea following structural changes within the University of Wales.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('fe1c96c5-b12f-493c-b433-9bf9b3b84836'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/5/52/Edge_Hill_University_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Edge Hill University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/b/b4/Faculty_of_Health_and_Social_Care.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Edge Hill University, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Edge Hill University is a campus-based public university in Ormskirk, Lancashire, England. The university, which originally opened in 1885 as Edge Hill College, was the first non-denominational teacher training college for women in England, before admitting its first male students in 1959. In 2005, Edge Hill was granted Taught Degree Awarding Powers by the Privy Council and became Edge Hill University on 18 May 2006.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('20c8103c-7381-4c05-abf6-dbdc42370a45'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Aston_Webb_buildings_in_snow%2C_The_University_of_Birmingham%2C_Dec_2009.jpg/1280px-Aston_Webb_buildings_in_snow%2C_The_University_of_Birmingham%2C_Dec_2009.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Simonham, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Birmingham is a public research university in Birmingham, England. It received its royal charter in 1900 as a successor to Queen's College, Birmingham, and Mason Science College, making it the first English redbrick university to receive its own royal charter, and the first English unitary university. It is a founding member of both the Russell Group of British research universities and the international network of research universities, Universitas 21.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('9f7b0689-8405-4bf6-85f3-17fb108eef91'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Imperial_College_London_new_logo.png/500px-Imperial_College_London_new_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Imperial College London, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/Imperial_College_London_down_Exhibition_Road.jpg/1280px-Imperial_College_London_down_Exhibition_Road.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Shadowssettle, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The Imperial College of Science, Technology and Medicine, known by its trade names Imperial College London and Imperial, is a public research university in London, England. Its history began with Prince Albert, husband of Queen Victoria, who envisioned South Kensington as a cultural district with museums, colleges, and the Royal Albert Hall. In 1907, two colleges – the Royal College of Science and the Royal School of Mines – merged to form Imperial College London, with City and Guilds College joining in 1910.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d2dc287f-fd70-4fa2-b9a8-a94535227446'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Founder%27s_Building%2C_Royal_Holloway%2C_south_quad.jpg/1280px-Founder%27s_Building%2C_Royal_Holloway%2C_south_quad.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Rwendland, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Royal Holloway, University of London, formally incorporated as Royal Holloway and Bedford New College, is a public research university and a member institution of the federal University of London. It has 3 faculties, 12 academic departments and approximately 10,500 undergraduate and postgraduate students from more than 100 countries. The campus is located west of Egham, Surrey, 19 miles from central London.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e0928483-71a7-4a37-bb05-da8b2c3b3e72'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Bangor_University_%2850555605717%29.jpg/1280px-Bangor_University_%2850555605717%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Andrew Woodvine from Bangor, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Bangor University is a public research university in Bangor, Gwynedd, Wales. It was established in 1884 as the University College of North Wales, and received a Royal Charter in 1885. In 1893 it became one of the founding institutions of the federal University of Wales.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ba9362a8-72d4-4170-b7e1-19abaea8ba72'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Lsbu-logo.svg/500px-Lsbu-logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/d/d5/London_southbank_university.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: The original uploader was Secretlondon at English Wikipedia., CC BY-SA 3.0, Wikimedia Commons$q$,$q$London South Bank University is a public university in Elephant and Castle, London. It is based in the London Borough of Southwark, near the South Bank of the River Thames, from which it takes its name. Founded in 1892 as the Borough Polytechnic Institute, it achieved university status in 1992 under the Further and Higher Education Act 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('890c87b2-1836-466d-9c21-682267722e24'::uuid,NULL,NULL,NULL,NULL,$q$The University of Sunderland is a public research university located in Sunderland in the North East of England. Its predecessor, Sunderland Technical College, was established as a municipal training college in 1901. It gained university status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c38015a2-293b-4a2a-9a98-10da18f519b8'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/University_of_East_London_logo.svg/500px-University_of_East_London_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/4/40/University_of_East_London_-_geograph.org.uk_-_54115.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Glyn Baker, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of East London is a public university located in the London Borough of Newham, London, England, based at three campuses in Stratford and Docklands, following the opening of University Square Stratford in September 2013. The University of East London began as the West Ham Technical Institute and it was officially opened in October 1898 after approval was given for the construction of the site by the West Ham Technical Instruction Act Committee in 1892 following the Technical Instruction Act 1889. It gained university status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('52c33587-b13a-4e4c-8216-2419db331ddb'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0d/UoN_Newton.jpg/1280px-UoN_Newton.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: StJaBe, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Northampton is a public university based in Northampton, Northamptonshire, England. It was formed in 1975 as Nene College of Higher Education by the amalgamation of a number of training colleges and gained university college status as University College Northampton in 1999 and full university status as the University of Northampton in 2005.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4980c212-d9a5-4a5d-89c1-7bfa05c61427'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Logo_Nottingham_Trent_University.svg/500px-Logo_Nottingham_Trent_University.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Byron_house_2.JPG/1280px-Byron_house_2.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Superhasn at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$Nottingham Trent University is a public research university located in Nottingham, England, which lies along the River Trent. Its origins date back to the establishment of the Nottingham Government School of Design in 1843, one of the earliest institutions of its kind in the United Kingdom. The university assumed its current status in 1992.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('cf14321d-6c4b-478e-9b43-f3f2d33c5a97'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Hawthorn_Building2.jpg/1280px-Hawthorn_Building2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jack O'Sullivan, CC BY 2.0, Wikimedia Commons$q$,$q$De Montfort University Leicester is a public university in Leicester, England.  The university traces its origins to the Leicester School of Art, founded in 1870, and gained university status in 1992 under the Further and Higher Education Act. It is named after Simon de Montfort, a 13th-century Earl of Leicester who played a major role in the constitutional development of England.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a6eaa4c7-f554-438c-bdff-44599747e72f'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/University_of_Oxford.svg/500px-University_of_Oxford.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Oxford, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/1_oxford_aerial_panorama_2016.jpg/1280px-1_oxford_aerial_panorama_2016.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Chensiyuan, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Oxford is a collegiate research university in Oxford, England. There is evidence of teaching as early as 1096, making it the oldest university in the English-speaking world and the world's second-oldest university in continuous operation. It grew rapidly from 1167, when Henry II prohibited English students from attending the University of Paris.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('fc9cd755-1aae-486d-afdf-394431413b1f'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Bishop_Grosseteste_University.jpg/1280px-Bishop_Grosseteste_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Paul Stainthorp, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Lincoln Bishop University, known until 2025 as Bishop Grosseteste University, is a public university in the city of Lincoln, England. LBU was established as a teacher training college for the Diocese of Lincoln in 1862. It gained taught degree awarding powers in 2012, applied for full university status, and was granted on 3 December 2012.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('912da2b5-27ca-464f-8917-3b1fda7d4c98'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/University_of_Hull_arms.svg/500px-University_of_Hull_arms.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Hogweard, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/6/61/Venn_Building%2C_University_of_Hull.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Stephen Horncastle, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Hull is a public research university in Kingston upon Hull, a city in the East Riding of Yorkshire, England. It was founded in 1927 as University College Hull. The main university campus is located in Hull and is home to the Hull York Medical School, a joint initiative with the University of York.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('020fbf24-f98a-44fb-9f13-cd1362f203d5'::uuid,NULL,NULL,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/University_of_Bath.jpg/1280px-University_of_Bath.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Bath is a public research university in Bath, England. Bath received its royal charter in 1966 as Bath University of Technology, along with a number of other institutions following the Robbins Report. Like the University of Bristol and University of the West of England, Bath traces its roots to the Merchant Venturers' Technical College, established as Bristol Trade School in 1856.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$)
) as v(id,logo_url,logo_credit,image_url,image_credit,description,description_credit)
where s.id = v.id;
